using BARANG.Core.Domain.Security;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Organization = BARANG.Core.Domain.Organization;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class SecurityConfiguration
{
    public static void Id<T>(EntityTypeBuilder<T> b) where T : class => b.Property("Id").HasColumnName("id");
    public static void Versioned<T>(EntityTypeBuilder<T> b) where T : class { b.Property("CreatedAtUtc").HasColumnName("created_at_utc"); b.Property("UpdatedAtUtc").HasColumnName("updated_at_utc"); b.Property("Version").HasColumnName("version").IsConcurrencyToken(); }
}
internal sealed class ApplicationUserConfiguration : IEntityTypeConfiguration<ApplicationUser> { public void Configure(EntityTypeBuilder<ApplicationUser> b) { b.ToTable("application_users", t => { t.HasCheckConstraint("ck_application_users_version_positive", "version > 0"); t.HasCheckConstraint("ck_application_users_access_failed_nonnegative", "access_failed_count >= 0"); }); b.HasKey(x => x.Id).HasName("pk_application_users"); SecurityConfiguration.Id(b); b.Property(x => x.PersonId).HasColumnName("person_id"); b.Property(x => x.Username).HasColumnName("username").HasMaxLength(100); b.Property(x => x.Email).HasColumnName("email").HasMaxLength(320); b.Property(x => x.DisplayName).HasColumnName("display_name").HasMaxLength(200); b.Property(x => x.AccountState).HasColumnName("account_state").HasConversion<string>().HasMaxLength(32); b.Property(x => x.PasswordHash).HasColumnName("password_hash").HasMaxLength(512); b.Property(x => x.SecurityStamp).HasColumnName("security_stamp").HasMaxLength(64); b.Property(x => x.LockoutEndUtc).HasColumnName("lockout_end_utc"); b.Property(x => x.AccessFailedCount).HasColumnName("access_failed_count"); b.Property(x => x.LastLoginAtUtc).HasColumnName("last_login_at_utc"); SecurityConfiguration.Versioned(b); b.HasOne<Organization.Person>().WithOne().HasForeignKey<ApplicationUser>(x=>x.PersonId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_application_users_persons_person_id"); b.HasIndex(x => x.PersonId).IsUnique().HasFilter("person_id IS NOT NULL").HasDatabaseName("ux_application_users_person_id"); b.HasIndex(x => x.Username).IsUnique().HasDatabaseName("uq_application_users_username"); } }
internal sealed class RoleConfiguration : IEntityTypeConfiguration<Role> { public void Configure(EntityTypeBuilder<Role> b) { b.ToTable("roles", t => t.HasCheckConstraint("ck_roles_version_positive", "version > 0")); b.HasKey(x => x.Id).HasName("pk_roles"); SecurityConfiguration.Id(b); b.Property(x => x.Code).HasColumnName("code").HasMaxLength(100); b.Property(x => x.DisplayTitle).HasColumnName("display_title").HasMaxLength(200); b.Property(x => x.Description).HasColumnName("description").HasMaxLength(1000); b.Property(x => x.Scope).HasColumnName("scope").HasConversion<string>().HasMaxLength(32); b.Property(x => x.IsSystem).HasColumnName("is_system"); b.Property(x => x.IsActive).HasColumnName("is_active"); SecurityConfiguration.Versioned(b); b.HasIndex(x => x.Code).IsUnique().HasDatabaseName("uq_roles_code"); } }
internal sealed class PermissionConfiguration : IEntityTypeConfiguration<Permission> { public void Configure(EntityTypeBuilder<Permission> b) { b.ToTable("permissions"); b.HasKey(x => x.Id).HasName("pk_permissions"); SecurityConfiguration.Id(b); b.Property(x => x.Code).HasColumnName("code").HasMaxLength(150); b.Property(x => x.TechnicalDescription).HasColumnName("technical_description").HasMaxLength(300); b.Property(x => x.Module).HasColumnName("module").HasMaxLength(64); b.HasIndex(x => x.Code).IsUnique().HasDatabaseName("uq_permissions_code"); b.HasData(SecurityPermissions.All.Select((code, index) => Permission.Create(Guid.Parse($"00000000-0000-0000-0000-{index + 1:000000000000}"), code, code, code.Split('.')[0]))); } }
internal sealed class RolePermissionConfiguration : IEntityTypeConfiguration<RolePermission> { public void Configure(EntityTypeBuilder<RolePermission> b) { b.ToTable("role_permissions"); b.HasKey(x => x.Id).HasName("pk_role_permissions"); SecurityConfiguration.Id(b); b.Property(x => x.RoleId).HasColumnName("role_id"); b.Property(x => x.PermissionId).HasColumnName("permission_id"); b.Property(x => x.AssignedAtUtc).HasColumnName("assigned_at_utc"); b.Property(x => x.AssignedByUserId).HasColumnName("assigned_by_user_id"); b.HasOne<Role>().WithMany().HasForeignKey(x => x.RoleId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_role_permissions_roles_role_id"); b.HasOne<Permission>().WithMany().HasForeignKey(x => x.PermissionId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_role_permissions_permissions_permission_id"); b.HasIndex(x => new { x.RoleId, x.PermissionId }).IsUnique().HasDatabaseName("uq_role_permissions_role_id_permission_id"); } }
internal sealed class UserPermissionConfiguration : IEntityTypeConfiguration<UserPermission> { public void Configure(EntityTypeBuilder<UserPermission> b) { b.ToTable("user_permissions"); b.HasKey(x => x.Id).HasName("pk_user_permissions"); SecurityConfiguration.Id(b); b.Property(x => x.UserId).HasColumnName("user_id"); b.Property(x => x.PermissionId).HasColumnName("permission_id"); b.Property(x => x.CompanyId).HasColumnName("company_id"); b.Property(x => x.AssignedAtUtc).HasColumnName("assigned_at_utc"); b.Property(x => x.AssignedByUserId).HasColumnName("assigned_by_user_id"); b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_permissions_application_users_user_id"); b.HasOne<Permission>().WithMany().HasForeignKey(x => x.PermissionId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_permissions_permissions_permission_id"); b.HasOne<Organization.Company>().WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_permissions_companies_company_id"); b.HasIndex(x => new { x.CompanyId, x.UserId }).HasDatabaseName("ix_user_permissions_company_id_user_id"); b.HasIndex(x => new { x.UserId, x.PermissionId, x.CompanyId }).IsUnique().HasDatabaseName("uq_user_permissions_user_id_permission_id_company_id"); } }
internal sealed class UserCompanyConfiguration : IEntityTypeConfiguration<UserCompany> { public void Configure(EntityTypeBuilder<UserCompany> b) { b.ToTable("user_companies", t => t.HasCheckConstraint("ck_user_companies_valid_period", "valid_to_utc IS NULL OR valid_to_utc > valid_from_utc")); b.HasKey(x => x.Id).HasName("pk_user_companies"); SecurityConfiguration.Id(b); b.Property(x => x.UserId).HasColumnName("user_id"); b.Property(x => x.CompanyId).HasColumnName("company_id"); b.Property(x => x.ValidFromUtc).HasColumnName("valid_from_utc"); b.Property(x => x.ValidToUtc).HasColumnName("valid_to_utc"); b.Property(x => x.GrantedAtUtc).HasColumnName("granted_at_utc"); b.Property(x => x.GrantedByUserId).HasColumnName("granted_by_user_id"); b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_companies_application_users_user_id"); b.HasOne<Organization.Company>().WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_companies_companies_company_id"); b.HasIndex(x => new { x.CompanyId, x.UserId }).HasDatabaseName("ix_user_companies_company_id_user_id"); b.HasIndex(x => new { x.UserId, x.CompanyId }).HasFilter("valid_to_utc IS NULL").IsUnique().HasDatabaseName("ux_user_companies_user_id_company_id_open"); } }
internal sealed class UserRoleConfiguration : IEntityTypeConfiguration<UserRole> { public void Configure(EntityTypeBuilder<UserRole> b) { b.ToTable("user_roles", t => t.HasCheckConstraint("ck_user_roles_valid_period", "valid_to_utc IS NULL OR valid_to_utc > valid_from_utc")); b.HasKey(x => x.Id).HasName("pk_user_roles"); SecurityConfiguration.Id(b); b.Property(x => x.UserId).HasColumnName("user_id"); b.Property(x => x.RoleId).HasColumnName("role_id"); b.Property(x => x.CompanyId).HasColumnName("company_id"); b.Property(x => x.ValidFromUtc).HasColumnName("valid_from_utc"); b.Property(x => x.ValidToUtc).HasColumnName("valid_to_utc"); b.Property(x => x.AssignedAtUtc).HasColumnName("assigned_at_utc"); b.Property(x => x.AssignedByUserId).HasColumnName("assigned_by_user_id"); b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_roles_application_users_user_id"); b.HasOne<Role>().WithMany().HasForeignKey(x => x.RoleId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_roles_roles_role_id"); b.HasOne<Organization.Company>().WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_user_roles_companies_company_id"); b.HasIndex(x => new { x.CompanyId, x.UserId }).HasDatabaseName("ix_user_roles_company_id_user_id"); b.HasIndex(x => new { x.UserId, x.RoleId, x.CompanyId }).HasFilter("valid_to_utc IS NULL").IsUnique().HasDatabaseName("ux_user_roles_user_id_role_id_company_id_open"); } }
internal sealed class AuthenticationSessionConfiguration : IEntityTypeConfiguration<AuthenticationSession> { public void Configure(EntityTypeBuilder<AuthenticationSession> b) { b.ToTable("authentication_sessions"); b.HasKey(x => x.Id).HasName("pk_authentication_sessions"); SecurityConfiguration.Id(b); b.Property(x => x.UserId).HasColumnName("user_id"); b.Property(x => x.TokenHash).HasColumnName("token_hash").HasMaxLength(64); b.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); b.Property(x => x.ExpiresAtUtc).HasColumnName("expires_at_utc"); b.Property(x => x.RevokedAtUtc).HasColumnName("revoked_at_utc"); b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_authentication_sessions_application_users_user_id"); b.HasIndex(x => x.TokenHash).IsUnique().HasDatabaseName("uq_authentication_sessions_token_hash"); } }
internal sealed class ApiClientConfiguration : IEntityTypeConfiguration<ApiClient> { public void Configure(EntityTypeBuilder<ApiClient> b) { b.ToTable("api_clients", t => t.HasCheckConstraint("ck_api_clients_version_positive", "version > 0")); b.HasKey(x => x.Id).HasName("pk_api_clients"); SecurityConfiguration.Id(b); b.Property(x => x.Code).HasColumnName("code").HasMaxLength(100); b.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); b.Property(x => x.IsActive).HasColumnName("is_active"); b.Property(x => x.CredentialFingerprint).HasColumnName("credential_fingerprint").HasMaxLength(128); b.Property(x => x.CredentialExpiresAtUtc).HasColumnName("credential_expires_at_utc"); SecurityConfiguration.Versioned(b); b.HasIndex(x => x.Code).IsUnique().HasDatabaseName("uq_api_clients_code"); } }
internal sealed class ApiClientCompanyConfiguration : IEntityTypeConfiguration<ApiClientCompany> { public void Configure(EntityTypeBuilder<ApiClientCompany> b) { b.ToTable("api_client_companies"); b.HasKey(x => x.Id).HasName("pk_api_client_companies"); SecurityConfiguration.Id(b); b.Property(x => x.ApiClientId).HasColumnName("api_client_id"); b.Property(x => x.CompanyId).HasColumnName("company_id"); b.HasOne<ApiClient>().WithMany().HasForeignKey(x => x.ApiClientId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_api_client_companies_api_clients_api_client_id"); b.HasOne<Organization.Company>().WithMany().HasForeignKey(x => x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_api_client_companies_companies_company_id"); b.HasIndex(x => new { x.ApiClientId, x.CompanyId }).IsUnique().HasDatabaseName("uq_api_client_companies_api_client_id_company_id"); } }
internal sealed class ApiClientPermissionConfiguration : IEntityTypeConfiguration<ApiClientPermission> { public void Configure(EntityTypeBuilder<ApiClientPermission> b) { b.ToTable("api_client_permissions"); b.HasKey(x => x.Id).HasName("pk_api_client_permissions"); SecurityConfiguration.Id(b); b.Property(x => x.ApiClientId).HasColumnName("api_client_id"); b.Property(x => x.PermissionId).HasColumnName("permission_id"); b.HasOne<ApiClient>().WithMany().HasForeignKey(x => x.ApiClientId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_api_client_permissions_api_clients_api_client_id"); b.HasOne<Permission>().WithMany().HasForeignKey(x => x.PermissionId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_api_client_permissions_permissions_permission_id"); b.HasIndex(x => new { x.ApiClientId, x.PermissionId }).IsUnique().HasDatabaseName("uq_api_client_permissions_api_client_id_permission_id"); } }
